class LinkedList {
    private static class Node {
        int value; Node next;
        Node(int value) { this.value = value; }
    }

    private Node head;
    private int size = 0;

    void add(int v) {
        Node n = new Node(v);
        if (head == null) { head = n; }
        else {
            Node cur = head;
            while (cur.next != null) cur = cur.next;
            cur.next = n;
        }
        size++;
    }

    boolean remove(int v) {
        if (head == null) return false;
        if (head.value == v) { head = head.next; size--; return true; }
        Node cur = head;
        while (cur.next != null) {
            if (cur.next.value == v) { cur.next = cur.next.next; size--; return true; }
            cur = cur.next;
        }
        return false;
    }

    boolean contains(int v) {
        Node cur = head;
        while (cur != null) { if (cur.value == v) return true; cur = cur.next; }
        return false;
    }

    int size() { return size; }
}

