class BinaryTree {
    private static class TreeNode {
        int value; TreeNode left, right;
        TreeNode(int value) { this.value = value; }
    }

    private TreeNode root;

    void insert(int v) { root = insertRec(root, v); }

    private TreeNode insertRec(TreeNode node, int v) {
        if (node == null) return new TreeNode(v);
        if (v < node.value) node.left = insertRec(node.left, v);
        else node.right = insertRec(node.right, v);
        return node;
    }

    boolean contains(int v) { return containsRec(root, v); }

    private boolean containsRec(TreeNode node, int v) {
        if (node == null) return false;
        if (node.value == v) return true;
        return v < node.value ? containsRec(node.left, v) : containsRec(node.right, v);
    }

    int[] inOrder() {
        List<Integer> list = new ArrayList<>();
        inOrderRec(root, list);
        int[] result = new int[list.size()];
        for (int i = 0; i < result.length; i++) result[i] = list.get(i);
        return result;
    }

    private void inOrderRec(TreeNode node, List<Integer> list) {
        if (node == null) return;
        inOrderRec(node.left, list);
        list.add(node.value);
        inOrderRec(node.right, list);
    }
}

