interface Transformer<T, R> { R transform(T value); }

abstract class Maybe<T> {
    static <T> Maybe<T> of(T value) { return new Just<>(value); }
    static <T> Maybe<T> empty() { return new Nothing<>(); }

    abstract boolean isPresent();
    abstract T get();
    abstract <R> Maybe<R> map(Transformer<T, R> t);

    private static class Just<T> extends Maybe<T> {
        private T value;
        Just(T value) { this.value = value; }
        boolean isPresent() { return true; }
        T get() { return value; }
        <R> Maybe<R> map(Transformer<T, R> t) { return Maybe.of(t.transform(value)); }
    }

    private static class Nothing<T> extends Maybe<T> {
        boolean isPresent() { return false; }
        T get() { throw new IllegalStateException("Brak wartosci"); }
        <R> Maybe<R> map(Transformer<T, R> t) { return Maybe.empty(); }
    }
}

