class TextEditor {
    private StringBuilder content = new StringBuilder();
    private List<Command> history = new ArrayList<>();

    abstract class Command {
        abstract void execute();
        abstract void undo();
    }

    class InsertCommand extends Command {
        private String text;
        InsertCommand(String text) { this.text = text; }
        void execute() { content.append(text); history.add(this); }
        void undo() { content.setLength(content.length() - text.length()); }
    }

    void undoLast() {
        if (!history.isEmpty()) {
            Command last = history.remove(history.size() - 1);
            last.undo();
        }
    }

    String getContent() { return content.toString(); }
}

