class Graph {
    private static class Edge {
        String from, to; int weight;
        Edge(String from, String to, int weight) { this.from = from; this.to = to; this.weight = weight; }
    }

    private java.util.List<Edge> edges = new java.util.ArrayList<>();
    private java.util.Set<String> vertices = new java.util.HashSet<>();

    void addVertex(String name) { vertices.add(name); }
    void addEdge(String from, String to, int weight) { edges.add(new Edge(from, to, weight)); }

    int shortestPath(String from, String to) {
        java.util.Map<String, Integer> dist = new java.util.HashMap<>();
        for (String v : vertices) dist.put(v, Integer.MAX_VALUE);
        dist.put(from, 0);

        for (int i = 0; i < vertices.size(); i++) {
            for (Edge e : edges) {
                if (dist.get(e.from) != Integer.MAX_VALUE && dist.get(e.from) + e.weight < dist.get(e.to)) {
                    dist.put(e.to, dist.get(e.from) + e.weight);
                }
            }
        }
        return dist.get(to);
    }
}

