interface Function { int apply(int n); }

class Memoize {
    static class Cache {
        int[] keys = new int[100];
        int[] values = new int[100];
        int size = 0;

        Integer get(int key) {
            for (int i = 0; i < size; i++) if (keys[i] == key) return values[i];
            return null;
        }

        void put(int key, int value) {
            keys[size] = key; values[size] = value; size++;
        }
    }

    static Function memoize(Function fn) {
        Cache cache = new Cache();
        return new Function() {
            public int apply(int n) {
                Integer cached = cache.get(n);
                if (cached != null) {
                    System.out.println("Cache hit dla " + n);
                    return cached;
                }
                int result = fn.apply(n);
                cache.put(n, result);
                return result;
            }
        };
    }
}

